fn all_characters_same(s: &[u8]) -> bool {
    // An empty slice or a single-element slice trivially has all characters identical.
    if s.len() < 2 {
        return true;
    }
    // Take the first byte and ensure every other byte matches it.
    let first = s[0];
    s.iter().skip(1).all(|&b| b == first)
}

